public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner(System.in);
        int n = scanner.nextInt();
        PrimeTable pt = new PrimeTable(n);
        MInt ans = MInt.zero();
        MInt acc = MInt.zero();
        for (int i = 1; i <= n; i++) {
            int c = pt.countDivisors(i);
            ans = acc.add(MInt.from(c));
            acc = acc.add(ans);
        }
        System.out.println(ans.inner());
    }

    // Modular integer for MOD = 998244353
    static class MInt {
        long x;

        MInt(long x) {
            this.x = x;
        }

        static MInt zero() {
            return new MInt(0);
        }

        static MInt one() {
            return new MInt(1);
        }

        static MInt from(long v) {
            long r = v % MOD;
            if (r < 0) r += MOD;
            return new MInt(r);
        }

        long inner() {
            return x;
        }

        MInt add(MInt other) {
            long z = x + other.x;
            if (z >= MOD) z -= MOD;
            return new MInt(z);
        }

        MInt sub(MInt other) {
            long z = x - other.x;
            if (z < 0) z += MOD;
            return new MInt(z);
        }

        MInt mul(MInt other) {
            return new MInt((x * other.x) % MOD);
        }

        MInt div(MInt other) {
            return mul(other.inv());
        }

        MInt neg() {
            if (x == 0) return new MInt(0);
            return new MInt(MOD - x);
        }

        MInt pow(long e) {
            long base = x;
            long res = 1;
            long y = e;
            while (y > 0) {
                if ((y & 1) == 1) {
                    res = (res * base) % MOD;
                }
                base = (base * base) % MOD;
                y >>= 1;
            }
            return new MInt(res);
        }

        MInt inv() {
            long a = x;
            long p = MOD;
            long b = p;
            long u = 1;
            long v = 0;
            while (a != 0) {
                long k = b / a;
                long tmp = v - k * u;
                v = u;
                u = tmp;
                long tmpB = b - k * a;
                b = a;
                a = tmpB;
            }
            long res = v;
            if (res < 0) res += p;
            return new MInt(res);
        }
    }

    // PrimeTable translated
    static class PrimeTable {
        int[] table;

        PrimeTable(int maxN) {
            int size = (maxN + 1) / 2;
            table = new int[size];
            Arrays.fill(table, 1);
            if (size > 0) table[0] = 0;
            for (int i = 3; ; i += 2) {
                long i2 = (long) i * (long) i;
                if (i2 > maxN) break;
                if (table[i >> 1] == 1) {
                    for (int j = (int) i2; j <= maxN; j += i * 2) {
                        int idx = j >> 1;
                        if (table[idx] == 1) {
                            table[idx] = i;
                        }
                    }
                }
            }
        }

        boolean isPrime(int n) {
            return n == 2 || (n % 2 == 1 && table[n >> 1] == 1);
        }

        interface FactorConsumer {
            void accept(int p, int c);
        }

        void forEach(int n, FactorConsumer f) {
            int k = Integer.numberOfTrailingZeros(n);
            if (k > 0) {
                f.accept(2, k);
            }
            n >>= k;
            while (table[n >> 1] > 1) {
                int p = table[n >> 1];
                int cnt = 1;
                n /= p;
                while (table[n >> 1] == p) {
                    n /= p;
                    cnt++;
                }
                if (n == p) {
                    cnt++;
                    n /= p;
                }
                f.accept(p, cnt);
            }
            if (n > 1) {
                f.accept(n, 1);
            }
        }

        List<int[]> primeFactors(int n) {
            List<int[]> factors = new ArrayList<>();
            forEach(n, (p, c) -> factors.add(new int[]{p, c}));
            return factors;
        }

        int countDivisors(int n) {
            final int[] divisorCnt = {1};
            forEach(n, (p, cnt) -> divisorCnt[0] *= (cnt + 1));
            return divisorCnt[0];
        }
    }

    // Simple fast scanner
    static class FastScanner {
        private final BufferedInputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = new BufferedInputStream(is);
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

